set-variable.value:
@{
    if (context.Api.Path != "ai4ia-attempts-v1" ||
        context.Subscription == null ||
        context.Subscription.Id != "__AI4IA_ATTEMPTS_SUBSCRIPTION_ID__" ||
        context.Request.Method != "POST") { return ""; }
    var headers = context.Request.Headers;
    if (!headers.ContainsKey("x-ai4ia-attempt") ||
        !headers.ContainsKey("x-ai4ia-proxy-attempt") ||
        !headers.ContainsKey("x-LLMModel") ||
        headers["x-LLMModel"].Length != 1) { return ""; }
    string path = context.Request.OriginalUrl.Path;
    var match = System.Text.RegularExpressions.Regex.Match(path,
        @"\A/ai4ia-attempts-v1/openai/(responses|deployments/([A-Za-z0-9_.-]+)/(chat/completions|embeddings))\z");
    string query = context.Request.OriginalUrl.QueryString;
    if (!match.Success || (!string.IsNullOrEmpty(query) &&
        !System.Text.RegularExpressions.Regex.IsMatch(query, @"\A\??api-version=[A-Za-z0-9_.-]{1,64}\z"))) { return ""; }
    string model = headers["x-LLMModel"][0];
    if (!System.Text.RegularExpressions.Regex.IsMatch(model, @"\A[A-Za-z0-9_.-]+\z") ||
        (match.Groups[2].Success && match.Groups[2].Value != model)) { return ""; }
    byte[] bytes = context.Request.Body.As<byte[]>(preserveContent: true);
    if (bytes.Length == 0 || bytes.Length > 1048576) { return ""; }
    JObject body = context.Request.Body.As<JObject>(preserveContent: true);
    if ((match.Groups[1].Value == "responses" && body["model"] == null) ||
        (body["model"] != null && (body["model"].Type != JTokenType.String ||
        body["model"].Value<string>() != model))) { return ""; }
    return match.Groups[1].Value;
  }
